if {{customNeutral}} {t.InvertedBackground=ui.Hex("#7e22ce");if t.Dark {t.InvertedBackground=ui.Hex("#c084fc")}}
var avatar *nui.AvatarOptions
if {{avatar}} {avatar=&nui.AvatarOptions{Alt:"Ada Lovelace"}}
nui.Badge(c.Key("badge"),t,{{label}},nui.BadgeOptions{Color: {{color}}, Size: {{size}}, Variant: {{variant}},Leading:{{icon}},Avatar:avatar,Square:{{square}}}).AlignSelf(ui.Start).Label("Badge preview")

if {{customNeutral}} {t.InvertedBackground=ui.Hex("#7e22ce");if t.Dark {t.InvertedBackground=ui.Hex("#c084fc")}}
