if !s.Hidden { nui.Alert(c.Key("alert"),t,nui.AlertOptions{Title:{{label}},Description:{{description}},Color:{{color}},Variant:{{variant}},Icon:lucide.Info(),Avatar:avatar,Orientation:nui.Set({{orientation}}),Close:closeOptions,CloseIcon:closeIcon,OnClose:onClose,Actions:func(){nui.Button(c.Key("review"),t,"Review changes",nui.ButtonOptions{Size:nui.XS,Color:nui.Neutral,Variant:nui.Subtle}).OnClick(func(){s.Reviewed++})}}) }
ui.Textf(c,"Reviewed %d times; closed %d times",s.Reviewed,s.Closed)

items:=[]nui.AvatarItem{{ID:"ada",Avatar:nui.AvatarOptions{Alt:"Ada Lovelace"}},{ID:"grace",Avatar:nui.AvatarOptions{Alt:"Grace Hopper"}},{ID:"lin",Avatar:nui.AvatarOptions{Alt:"Lin Chen"}}}
if s.Reverse { for i,j:=0,len(items)-1;i<j;i,j=i+1,j-1 {items[i],items[j]=items[j],items[i]} }
var styles nui.Styles
if {{memberStyle}} {styles=nui.Styles{nui.Item:{Radius:nui.Set(float32(8)),BorderColor:nui.Set(t.Primary),BorderWidth:nui.Set(float32(2))}}}
nui.AvatarGroup(c.Key("avatars"),t,items,nui.AvatarGroupOptions{Max:nui.Set({{maximum}}),Size:{{size}},Color:{{color}},UI:styles})
nui.Button(c.Key("reverse"),t,"Reverse avatars",nui.ButtonOptions{Size:nui.XS,Variant:nui.Outline}).OnClick(func(){s.Reverse=!s.Reverse})

if {{customNeutral}} {t.InvertedBackground=ui.Hex("#7e22ce")}
var content func()
if !{{standalone}} { content=func(){nui.Button(c.Key("host"),t,"Notifications",nui.ButtonOptions{Variant:nui.Outline,AccessibleLabel:"Notifications "+{{label}}}).OnClick(func(){s.Count++})} }
var styles nui.Styles
if {{styledText}} {styles=nui.Styles{nui.Indicator:{Font:nui.Set(t.MonoFont),FontSize:nui.Set(float32(14)*t.TextScale),PaddingX:nui.Set(float32(4))}}}
nui.Chip(c.Key("chip"),t,nui.ChipOptions{Text:{{label}},Color:{{color}},Size:{{size}},Hidden:{{hidden}},Position:{{position}},Inset:{{inset}},UI:styles,Style:func(slot nui.Slot,e ui.Element){if slot==nui.Indicator && {{styledText}} {e.Height(18*t.TextScale)}}},content).AlignSelf(ui.Start)
ui.Textf(c,"Host actions: %d",s.Count)

var avatar *nui.AvatarOptions
if {{avatar}} {avatar=&nui.AvatarOptions{Alt:"Separator member"}}
