options:=nui.SeparatorOptions{Label:{{label}},Color:{{color}},Size:{{size}},Orientation:{{orientation}},Position:{{position}},Type:{{lineType}},Avatar:avatar,Content:content}
part:=nui.Separator(c.Key("separator"),t,options)
if options.Vertical || options.Orientation==nui.Vertical {part.Width(180).Height(160)}
ui.Text(c,"Draft: "+s.Draft)

if {{customNeutral}} { t.InvertedBackground = ui.Hex("#7e22ce"); if t.Dark { t.InvertedBackground = ui.Hex("#c084fc") } }
