nui.ProgressGroup(c.Key("progress"), t, []nui.ProgressSegment{{ID: "code", Label: "Code", Value: 45, Icon: codeIcon}, {ID: "tests", Label: "Tests", Value: 30, Color: nui.Info, Icon: testIcon, UI: segmentUI}, {ID: "docs", Label: "Docs", Value: 15, Color: nui.Warning, Icon: docIcon}}, nui.ProgressGroupOptions{Label: "Project progress", Color: {{color}}, Size: {{size}}, Max: nui.Set(float64({{max}})), HideLegend: {{hideLegend}}, Orientation: {{orientation}}, Height: 160})

