if {{customBody}} { body = func() { nui.Button(c.Key("custom"), t, "Complete custom body", nui.ButtonOptions{}).OnClick(func() { s.Created++ }) } }
var parts nui.Styles
if {{loadingColor}} { parts = nui.Styles{nui.Leading: {Foreground: nui.Set(t.Error)}} }
nui.Empty(c.Key("empty"), t, nui.EmptyOptions{Title: {{label}}, Description: "Create a project to get started.", Icon: icon, Avatar: avatar, Size: {{size}}, Variant: {{variant}}, Loading: {{loading}}, Header: header, Body: body, Actions: func() { nui.Button(c.Key("create"), t, "Create project", nui.ButtonOptions{}).OnClick(func() { s.Created++ }) }, Footer: func() { ui.Textf(c, "Created: %d", s.Created) }, Decoration: nui.Decoration{UI: parts}})

avatar := nui.AvatarOptions{}
if {{avatar}} { avatar.Alt = {{label}} }
var chip *nui.ChipOptions
if {{chip}} { chip = &nui.ChipOptions{Color: nui.Success, Text: "3"} }
var activate func()
if {{interactive}} { activate = func() { s.Activated++ } }
var body func()
if {{customBody}} { body = func() { ui.Text(c, "Custom user content"); ui.Text(c, {{label}}) } }
nui.User(c.Key("user"), t, nui.UserOptions{Name: {{label}}, Description: "Maintainer", Avatar: avatar, Chip: chip, Size: {{size}}, Vertical: {{vertical}}, Disabled: {{disabled}}, OnActivate: activate, Body: body})
ui.Textf(c, "Activated: %d", s.Activated)

if {{customNeutral}} { t.InvertedBackground = ui.Hex("#7e22ce"); if t.Dark { t.InvertedBackground = ui.Hex("#c084fc") } }
var avatar *nui.AvatarOptions
if {{avatar}} { avatar = &nui.AvatarOptions{Alt: "Input preview avatar", Text: "AL"} }
var parts nui.Styles
if {{loadingColor}} { parts = nui.Styles{nui.Leading: {Foreground: nui.Set(t.Error)}, nui.Trailing: {Foreground: nui.Set(t.Error)}} }
nui.Input(c.Key("input"), t, &s.Value, nui.InputOptions{Label: {{label}}, Placeholder: {{placeholder}}, Color: {{color}}, Size: {{size}}, Variant: {{variant}}, Disabled: {{disabled}}, ReadOnly: {{readOnly}}, Loading: {{loading}}, LoadingTrailing: {{loadingTrailing}}, Avatar: avatar, Clearable: {{clearable}}, Highlight: {{highlight}}, UI: parts, OnChange: func(string) { s.Changes++ }, OnSubmit: func(string) { s.Submits++ }, OnClear: func() { s.Clears++ }}).FillWidth()
