if {{customNeutral}} { t.InvertedBackground = ui.Hex("#7e22ce"); if t.Dark { t.InvertedBackground = ui.Hex("#c084fc") } }
var avatar *nui.AvatarOptions
if {{avatar}} { avatar = &nui.AvatarOptions{Alt: "Textarea preview avatar", Text: "AL"} }
var parts nui.Styles
if {{loadingColor}} { parts = nui.Styles{nui.Leading: {Foreground: nui.Set(t.Error)}, nui.Trailing: {Foreground: nui.Set(t.Error)}} }
nui.Textarea(c.Key("textarea"), t, &s.Value, nui.TextareaOptions{InputOptions: nui.InputOptions{Label: {{label}}, Placeholder: {{placeholder}}, Color: {{color}}, Size: {{size}}, Variant: {{variant}}, Disabled: {{disabled}}, ReadOnly: {{readOnly}}, Loading: {{loading}}, LoadingTrailing: {{loadingTrailing}}, Avatar: avatar, Clearable: {{clearable}}, Highlight: {{highlight}}, UI: parts, OnChange: func(string) { s.Changes++ }, OnClear: func() { s.Clears++ }}, Rows: {{rows}}, MaxRows: {{maxRows}}, AutoResize: {{autoResize}}}).FillWidth()
ui.Textf(c,"Changes: %d · Clears: %d",s.Changes,s.Clears)

