nui.FormField(c.Key("field"), t, nui.FormFieldOptions{Label: {{label}}, Description: {{description}}, Hint: {{hint}}, Help: {{help}}, Required: {{required}}, Disabled: {{disabled}}, Error: {{error}}, Size: {{size}}, Orientation: nui.Set(orientation), Decoration: nui.Decoration{UI: parts}}, func(ft nui.Theme) { nui.Input(c.Key("input"), ft, &s.Value, nui.InputOptions{Label: cmp.Or({{label}}, "Project input"), Placeholder: "Project name"}).Width(240) }).FillWidth()
ui.Text(c, "Value: "+s.Value)

items := []nui.FieldGroupItem{{ID: "input", Build: func(c *ui.Context, inner nui.Theme) ui.Element { return nui.Input(c, inner, &s.Value, nui.InputOptions{Label: "Search text", Placeholder: "Search"}).Grow(1).MinWidth(0) }}, {ID: "button", Build: func(c *ui.Context, inner nui.Theme) ui.Element { return nui.Button(c, inner, "Search", nui.ButtonOptions{Variant: nui.Outline}).OnClick(func() { s.Result = "Submitted: "+s.Value }) }}}
if {{reversed}} { items[0], items[1] = items[1], items[0] }
nui.FieldGroup(c.Key("group"), t, nui.FieldGroupOptions{Size: {{size}}, Disabled: {{disabled}}, Vertical: {{vertical}}}, items).FillWidth()
ui.Text(c, s.Result)

var checkedIcon, mixedIcon *ui.SVG
if {{customIcons}} {checkedIcon=lucide.Heart();mixedIcon=lucide.Plus()}
nui.FormField(c.Key("field"),t,nui.FormFieldOptions{Label:"Notification permission",Required:{{required}},Help:"Applies to this workspace"},func(field nui.Theme){
nui.Checkbox(c.Key("toggle"),field,&s.Value,nui.CheckboxOptions{Label:{{label}},Description:"Updates are saved locally in this example.",Color:{{color}},Size:{{size}},Disabled:{{disabled}},Loading:{{loading}},Variant:{{variant}},Indicator:{{indicator}},CheckedIcon:checkedIcon,OnChange:func(bool){s.Changes++}})
})
ui.Textf(c,"Enabled: %t",s.Value)
nui.CheckboxTri(c.Key("tri"),t,&s.Mixed,nui.CheckboxTriOptions{CheckboxOptions:nui.CheckboxOptions{Label:"Mixed selection",Disabled:{{disabled}},Color:{{color}},Size:{{size}},Variant:{{variant}},Indicator:{{indicator}},CheckedIcon:checkedIcon},IndeterminateIcon:mixedIcon,OnStateChange:func(nui.CheckState){s.MixedChanges++}})
nui.Button(c.Key("reset-mixed"),t,"Reset mixed state",nui.ButtonOptions{Variant:nui.Outline,Disabled:{{disabled}}}).OnClick(func(){s.Mixed=nui.Indeterminate})
ui.Textf(c,"Changes: %d / %d",s.Changes,s.MixedChanges)

var checkedIcon, uncheckedIcon, loadingIcon *ui.SVG
if {{customIcons}} {checkedIcon=lucide.Check();uncheckedIcon=lucide.X();loadingIcon=lucide.RefreshCw()}
nui.FormField(c.Key("field"),t,nui.FormFieldOptions{Label:"Sync policy",Help:"Applies to this workspace"},func(field nui.Theme){
nui.Switch(c.Key("toggle"),field,&s.Value,nui.SwitchOptions{Label:{{label}},Description:"Updates are saved locally in this example.",Color:{{color}},Size:{{size}},Disabled:{{disabled}},Loading:{{loading}},Highlight:{{highlight}},CheckedIcon:checkedIcon,UncheckedIcon:uncheckedIcon,LoadingIcon:loadingIcon,OnChange:func(bool){s.Changes++}})
})
ui.Textf(c,"Enabled: %t",s.Value)
ui.Textf(c,"Changes: %d",s.Changes)

items:=[]nui.Option[string]{{Value:"go",Label:"Go"},{Value:"rust",Label:"Rust"},{Value:"typescript",Label:"TypeScript"}}
if {{customIcons}} {for i:=range items {if items[i].Icon==nil {switch items[i].Value {case "go":items[i].Icon=lucide.Code();case "rust":items[i].Icon=lucide.Flame();default:items[i].Icon=lucide.FileCode()}}}}
if s.Reverse {for i,j:=0,len(items)-1;i<j;i,j=i+1,j-1 {items[i],items[j]=items[j],items[i]}}
nui.FormField(c.Key("field"),t,nui.FormFieldOptions{Label:"Language preferences"},func(field nui.Theme){
nui.CheckboxGroup(c.Key("choices"),field,&s.Values,items,nui.CheckboxGroupOptions{Label:"Languages",Color:{{color}},Size:{{size}},Disabled:{{disabled}},Horizontal:{{horizontal}},Variant:{{variant}},Indicator:{{indicator}},Loop:nui.Set({{loop}}),OnChange:func(){s.Changes++}})
})
ui.Textf(c,"Selected: %v",s.Values)
nui.Button(c.Key("reverse"),t,"Reverse choices",nui.ButtonOptions{Variant:nui.Outline}).OnClick(func(){s.Reverse=!s.Reverse})
ui.Textf(c,"Changes: %d",s.Changes)

items:=[]nui.Option[string]{{Value:"go",Label:"Go"},{Value:"rust",Label:"Rust"},{Value:"typescript",Label:"TypeScript"}}
if {{customIcons}} {for i:=range items {if items[i].Icon==nil {switch items[i].Value {case "go":items[i].Icon=lucide.Code();case "rust":items[i].Icon=lucide.Flame();default:items[i].Icon=lucide.FileCode()}}}}
if s.Reverse {for i,j:=0,len(items)-1;i<j;i,j=i+1,j-1 {items[i],items[j]=items[j],items[i]}}
nui.FormField(c.Key("field"),t,nui.FormFieldOptions{Label:"Language preferences"},func(field nui.Theme){
nui.RadioGroup(c.Key("choices"),field,&s.Value,items,nui.RadioGroupOptions{Label:"Languages",Color:{{color}},Size:{{size}},Disabled:{{disabled}},Horizontal:{{horizontal}},Variant:{{variant}},Indicator:{{indicator}},Loop:nui.Set({{loop}}),OnChange:func(){s.Changes++}})
})
ui.Textf(c,"Selected: %v",s.Value)
nui.Button(c.Key("reverse"),t,"Reverse choices",nui.ButtonOptions{Variant:nui.Outline}).OnClick(func(){s.Reverse=!s.Reverse})
ui.Textf(c,"Changes: %d",s.Changes)

if {{customNeutral}} { t.InvertedBackground = ui.Hex("#7e22ce"); if t.Dark { t.InvertedBackground = ui.Hex("#c084fc") } }
parts, singleParts := nui.Styles{}, nui.Styles{}
if {{customParts}} { parts[nui.Indicator] = nui.PartStyle{Background: nui.Set(t.Info)}; parts[nui.Thumb] = nui.PartStyle{Background: nui.Set(t.Elevated)}; for part, style := range parts { singleParts[part] = style } }
if {{padded}} { if {{vertical}} { singleParts[nui.Root] = nui.PartStyle{PaddingY: nui.Set(float32(48))} } else { singleParts[nui.Root] = nui.PartStyle{PaddingX: nui.Set(float32(48))} } }
errorText := ""
if {{fieldError}} { errorText = "Choose another value" }
orientation := nui.Horizontal
if {{vertical}} { orientation = nui.Vertical }
ui.Column(c.Key("controls")).Disabled({{parentDisabled}}).Gap(16).Children(func() {
nui.FormField(c.Key("single-field"), t, nui.FormFieldOptions{Error: errorText}, func(ft nui.Theme) {
nui.Slider(c.Key("slider"), ft, &s.Value, nui.SliderOptions{Label: "Volume", Min: nui.Set(0.0), Max: nui.Set(100.0), Step: {{step}}, Color: {{color}}, Size: {{size}}, Disabled: {{disabled}}, Vertical: {{vertical}}, Inverted: {{inverted}}, Tooltip: {{tooltip}}, OnChange: func(float64) { s.Changes++ }, OnCommit: func(float64) { s.Commits++ }, Decoration: nui.Decoration{UI: singleParts}})
})
ui.Textf(c,"Value: %g · Changes: %d · Commits: %d",s.Value,s.Changes,s.Commits)
nui.FormField(c.Key("range-field"), t, nui.FormFieldOptions{Error: errorText}, func(ft nui.Theme) {
nui.RangeSlider(c.Key("range"), ft, &s.Low, &s.High, nui.RangeSliderOptions{Label: "Range", Min: 0, Max: 100, Step: {{step}}, Color: {{color}}, Size: {{size}}, Disabled: {{disabled}}, Orientation: orientation, Inverted: {{inverted}}, Tooltip: {{tooltip}}, MinStepsBetweenThumbs: {{minimumGap}}, OnChange: func(float64, float64) { s.RangeChanges++ }, OnCommit: func(float64, float64) { s.RangeCommits++ }, Decoration: nui.Decoration{UI: parts}})
})
ui.Textf(c,"Range: %g – %g · Changes: %d · Commits: %d",s.Low,s.High,s.RangeChanges,s.RangeCommits)
})

if {{customNeutral}} { t.InvertedBackground = ui.Hex("#7e22ce"); if t.Dark { t.InvertedBackground = ui.Hex("#c084fc") } }
var avatar *nui.AvatarOptions
if {{avatar}} { avatar = &nui.AvatarOptions{Text:"GO",Alt:"Language avatar"} }
var leading, trailing, selected *ui.SVG
if {{customIcons}} { leading = lucide.Code(); trailing = lucide.ChevronsUpDown(); selected = lucide.Heart() }
items := []nui.Option[string]{{Value:"go",Label:"Go",Description:"Backend services",Icon:lucide.Code()},{Value:"rust",Label:"Rust",Description:"Native applications",Icon:lucide.Code()},{Value:"blocked",Label:"Disabled language",Disabled:true},{Value:"typescript",Label:"TypeScript",Description:"Web applications",Icon:lucide.Code()}}
nui.Select(c.Key("select"),t,&s.Value,items,nui.SelectOptions{Label:"Language",Placeholder:{{placeholder}},Color:{{color}},Size:{{size}},Variant:{{variant}},Disabled:{{disabled}},Avatar:avatar,Leading:leading,Trailing:trailing,SelectedIcon:selected,Loading:{{loading}},LoadingTrailing:{{loadingTrailing}},Highlight:{{highlight}},Open:&s.Open,OnChange:func(){s.Changes++}})
ui.Textf(c,"Selected: %s · Changes: %d · Open: %v",s.Value,s.Changes,s.Open)
nui.SelectMultiple(c.Key("multiple"),t,&s.Many,items,nui.SelectOptions{Label:"Multiple languages",Placeholder:{{placeholder}},Color:{{color}},Size:{{size}},Variant:{{variant}},Disabled:{{disabled}},Avatar:avatar,Leading:leading,Trailing:trailing,SelectedIcon:selected,Loading:{{loading}},LoadingTrailing:{{loadingTrailing}},Highlight:{{highlight}},Open:&s.ManyOpen,OnChange:func(){s.ManyChanges++}})
ui.Textf(c,"Selected IDs: %v · Changes: %d · Open: %v",s.Many,s.ManyChanges,s.ManyOpen)
nui.Button(c.Key("open-one"),t,"Toggle single select",nui.ButtonOptions{Variant:nui.Outline,Disabled:{{disabled}}}).OnClick(func(){s.Open=!s.Open})
nui.Button(c.Key("open-many"),t,"Toggle multiple select",nui.ButtonOptions{Variant:nui.Outline,Disabled:{{disabled}}}).OnClick(func(){s.ManyOpen=!s.ManyOpen})

disabled, readOnly := {{disabled}}, {{readOnly}}
var avatar *nui.AvatarOptions
if {{avatar}} { avatar = &nui.AvatarOptions{Text:"GO",Alt:"Search avatar"} }
var selectedIcon, deleteIcon, clearIcon *ui.SVG
if {{customIcons}} { selectedIcon=lucide.Heart(); deleteIcon=lucide.Minus(); clearIcon=lucide.Eraser() }
var onCreate func(string)
if {{create}} { onCreate=func(value string){s.Created=value} }
nui.InputMenu(c.Key("menu"),t,&s.Search,[]nui.Option[string]{{Value:"go",Label:"Go",Description:"Backend services",Icon:lucide.Code()},{Value:"rust",Label:"Rust",Description:"Native applications",Icon:lucide.Code()},{Value:"blocked",Label:"Disabled language",Disabled:true},{Value:"typescript",Label:"TypeScript",Description:"Web applications",Icon:lucide.Code()}},nui.InputMenuOptions{InputOptions:nui.InputOptions{Label:cmp.Or({{label}},"Language search"),Placeholder:{{placeholder}},Color:{{color}},Size:{{size}},Variant:{{variant}},Disabled:{{disabled}},ReadOnly:{{readOnly}},Loading:{{loading}},LoadingTrailing:{{loadingTrailing}},Avatar:avatar,Clearable:{{clearable}},OnChange:func(string){s.Queries++},OnClear:func(){s.Clears++},OnSubmit:func(string){s.Submits++}},Multiple:{{multiple}},Mode:{{mode}},Open:&s.Open,Loop:{{loop}},HighlightOnHover:{{highlightOnHover}},OpenOnClick:{{openOnClick}},OpenOnFocus:{{openOnFocus}},ResetSearchTermOnSelect:{{resetOnSelect}},ResetSearchTermOnBlur:{{resetOnBlur}},ResetModelValueOnClear:{{resetModel}},SelectedIcon:selectedIcon,DeleteIcon:deleteIcon,ClearIcon:clearIcon,OnCreate:onCreate,CreateAtTop:{{createAtTop}},OnSelect:func(string){s.Selections++},OnValuesChange:func([]string){s.Values++}})
ui.Textf(c,"Query: %s · Selected: %s · IDs: %v",s.Search.Query,s.Search.Selected,s.Search.SelectedValues)
ui.Textf(c,"Events: query %d · select %d · values %d · clear %d · submit %d",s.Queries,s.Selections,s.Values,s.Clears,s.Submits)
ui.Textf(c,"Open: %v · Create request: %s",s.Open,s.Created)
nui.Button(c.Key("toggle"),t,"Toggle search list",nui.ButtonOptions{Variant:nui.Outline,Disabled:disabled || readOnly}).OnClick(func(){s.Open=!s.Open})

t.Motion.Reduce = t.Motion.Reduce || {{reduced}}
parts:=nui.Styles{}
if {{styled}} {parts[nui.Panel]=nui.PartStyle{Background:nui.Set(t.Elevated),Foreground:nui.Set(t.Info),FontSize:nui.Set(float32(18)),LineHeight:nui.Set(float32(1.5)),Gap:nui.Set(float32(12))}}
options:=nui.PopoverOptions{Dismissible:{{dismissible}},Width:nui.Set(float32(240)),Decoration:nui.Decoration{UI:parts}}
ui.Column(c.Key("popover-stage")).Fill().Center().Children(func(){
var first, second ui.Element
ui.Row(c.Key("anchors")).Gap(8).Wrap().Children(func(){
first=nui.Button(c.Key("trigger"),t,{{label}},nui.ButtonOptions{AccessibleLabel:cmp.Or({{label}},"Example action")}).OnClick(func(){if options.Mode==nui.PopoverClick{s.Open=!s.Open}})
second=nui.Button(c.Key("alternate"),t,"Alternate anchor",nui.ButtonOptions{Variant:nui.Outline}).OnClick(func(){if options.Mode==nui.PopoverClick{s.Open=!s.Open}})
})
anchor:=first
if {{alternate}} {anchor=second}
nui.Popover(c.Key("popover"),t,anchor,&s.Open,options,func(inner nui.Theme){ui.Text(c,"Additional information");nui.Input(c.Key("draft"),inner,&s.Draft,nui.InputOptions{Label:"Popover draft"}).FillWidth();nui.Button(c.Key("close"),inner,"Close",nui.ButtonOptions{Variant:nui.Outline}).OnClick(func(){s.Open=false})})
})

direction := {{direction}}
radius:=float32(0)
if {{rounded}} {radius=16}
color:=nui.Optional[ui.Color]{}
if {{customColor}} {color=nui.Set(t.Info)}
options := nui.ScrollAreaOptions{Direction:direction,State:&s.Scroll,ScrollbarWidth:nui.Set(float32({{width}})),ScrollbarColor:color,Decoration:nui.Decoration{UI:nui.Styles{nui.Root:{Radius:nui.Set(radius)}},Style:func(part nui.Slot,e ui.Element){if part==nui.Body{e.Label("Scrollable records")}}}}
nui.ScrollArea(c.Key("scroll"),t,options,func(){for i:=range 30{row:=ui.Textf(c.Key(i),"Activity item %02d · Scrollable content",i+1).PaddingX(12).Background(t.Elevated);if options.Direction==nui.ScrollHorizontal{row.Width(180).Height(140)}else{row.Width(900).Height(40)}}}).Height(240).FillWidth()
if position:=options.State;position!=nil {
